//
// Shared GraphQL helpers for Forkable's hand-written novel commands. All
// novel features are live (pp:data-source live): Forkable's reads are POST
// GraphQL queries against a session-authenticated endpoint, and there is no
// GET-list sync path to mirror them. These helpers fetch a query live and
// return the decoded `data` object so novel commands can compute over it.
//
// This is a hand-authored file (no "Generated by ..." header) so
// `generate --force` preserves it.

package cli

import (
	"context"
	"encoding/json"
	"fmt"
)

const forkableGraphQLPath = "/api/v2/graphql"

// gqlError is one entry in a GraphQL `errors` array.
type gqlError struct {
	Message string `json:"message"`
}

// gqlEnvelope is the standard GraphQL-over-HTTP response envelope.
type gqlEnvelope struct {
	Data   json.RawMessage `json:"data"`
	Errors []gqlError      `json:"errors"`
}

// fetchGraphQL runs a GraphQL query live against Forkable and returns the
// raw `data` object. It surfaces GraphQL-level errors (which arrive with an
// HTTP 200) as a Go error so novel commands do not silently compute over an
// empty result.
func fetchGraphQL(ctx context.Context, flags *rootFlags, query string) (json.RawMessage, error) {
	c, err := flags.newClient()
	if err != nil {
		return nil, err
	}
	body := map[string]any{"query": query}
	// PostQueryWithParams marks this as a read so the verify-mode
	// short-circuit does not fire; the CSRF header is injected by the
	// client for the GraphQL path automatically.
	raw, status, err := c.PostQueryWithParams(ctx, forkableGraphQLPath, map[string]string{}, body)
	if err != nil {
		return nil, classifyAPIError(err, flags)
	}
	if status == 401 || status == 403 {
		return nil, fmt.Errorf("not authenticated (HTTP %d): run 'forkable-pp-cli auth login --chrome' after logging in to forkable.com in Chrome", status)
	}
	if status < 200 || status >= 300 {
		return nil, fmt.Errorf("forkable API returned HTTP %d", status)
	}
	var env gqlEnvelope
	if err := json.Unmarshal(raw, &env); err != nil {
		return nil, fmt.Errorf("parsing GraphQL response: %w", err)
	}
	if len(env.Errors) > 0 {
		return nil, fmt.Errorf("forkable GraphQL error: %s", env.Errors[0].Message)
	}
	if len(env.Data) == 0 {
		return nil, fmt.Errorf("forkable returned an empty GraphQL data payload")
	}
	return env.Data, nil
}
